func TestUpdateCommandForCurrentBinary_MiseRoots(t *testing.T) {
	installsDir := relocatedTestRoot("srv/tools")
	dataDir := relocatedTestRoot("srv/mise")
	tests := []struct {
		name        string
		installsDir string
		dataDir     string
		execPath    string
	}{
